                      #"SYSTEM_SYSRULES_recordActionItem"(
                        action: #"urn:appian:record-action:v1:fc71d9d0-6606-44d2-925f-c1307280df11/a6b1bffc-14c8-48d3-8ad7-09d2853b7bd6"
                      )
                    },
                    align: "END",
                    style: "LINKS",
                    display: "LABEL_AND_ICON"
                  )
                },
                width: "AUTO"
              )
            },
            alignVertical: "MIDDLE",
            spacing: "STANDARD"
          )
        },
        marginBelow: "STANDARD",
        style: "#1d2d44",
        showBorder: false,
        padding: "LESS"
      )
    },
    contents: 
    {
      #"SYSTEM_SYSRULES_gridField_v5"(
        label: "Tabla de solo lectura",
        labelPosition: "COLLAPSED",
        data: #"urn:appian:record-type:v1:fc71d9d0-6606-44d2-925f-c1307280df11",
        showRefreshButton: false,
        showSearchBox: false,
        similarityScoreThreshold: null,
        recordActions: {},
        columns: {
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Nombre",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: {
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: fv!row[#"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/a42f1b63-7bf1-49a1-a653-bbc56962b67b"] & " (" & fv!row[#"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/31441be1-b629-44d8-97c0-c9aa0a37e1c5"] & ")",
                  link: #"SYSTEM_SYSRULES_recordLink"(
                    recordType: #"urn:appian:record-type:v1:fc71d9d0-6606-44d2-925f-c1307280df11",
                    identifier: fv!row[#"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/c3f00363-8d89-4ef9-ace9-9470577498ee"]
                  ),
                  linkStyle: "STANDALONE"
                )
              }
            ),
            sortField: #"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/a42f1b63-7bf1-49a1-a653-bbc56962b67b",
            width: "MEDIUM_PLUS"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Misión/Visión",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: {
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: {fv!row[#"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/28bc9a3a-cd36-421a-b5c3-c76ebf2e254b"]}
                )
              },
              preventWrapping: true
            ),
            sortField: #"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/28bc9a3a-cd36-421a-b5c3-c76ebf2e254b",
            width: "AUTO"

          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Perspectiva estratégica",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: {
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: {fv!row[#"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/3d705e4a-2581-4d54-b62f-98991b769dfc"]}
                )
              },
              preventWrapping: true
            ),
            sortField: #"urn:appian:record-field:v1:fc71d9d0-6606-44d2-925f-c1307280df11/3d705e4a-2581-4d54-b62f-98991b769dfc",
            width: "AUTO"
          )
        },
        refreshAfter: "RECORD_ACTION",
        validations: {},
        shadeAlternateRows: true
      )
    },
    backgroundColor: "WHITE"
  )
)
